// 7 langues complètement traduites.
export const LOCALES = [
  ["en","🇬🇧","English"],["fr","🇫🇷","Français"],["es","🇪🇸","Español"],["de","🇩🇪","Deutsch"],
  ["it","🇮🇹","Italiano"],["pt","🇵🇹","Português"],["nl","🇳🇱","Nederlands"],
];
export const RTL = new Set(["ar", "he", "fa", "ur"]);
export const LANG_STORE = "mindlog.lang";


export function detectLang() {
  try {
    const s = localStorage.getItem(LANG_STORE);
    if (s) return s;
  } catch {}
  return (navigator.language || "en").slice(0, 2);
}
export let LANG = detectLang();
export function t(key) {
  const base = key.split(":")[0];
  return (I18N[LANG] && I18N[LANG][key]) ?? I18N.en[key] ?? base;
}
export function setLangCode(code) {
  LANG = code;
  try {
    localStorage.setItem(LANG_STORE, code);
  } catch {}
  document.documentElement.lang = code;
  document.documentElement.dir = RTL.has(code) ? "rtl" : "ltr";
}
export function langSelectHtml() {
  const cur = LOCALES.find((l) => l[0] === LANG) ? LANG : "en";
  return `<select id="lang-select" class="lang-select" aria-label="${t("lang_label")}">
    ${LOCALES.map((l) => `<option value="${l[0]}" ${l[0] === cur ? "selected" : ""}>${l[1]} ${l[2]}</option>`).join("")}
  </select>`;
}

// Crédit auteur, affiché dans les pieds de page.
export const CREDIT = () => `${t("credit")} <a href="https://le-lab.net" target="_blank" rel="noopener">le-lab.net</a>`;
